      "io": {
        "when": "len == 0",
        "returns": "0"
      }
    },
    {
      "id": "3",
      "type": "IO",
      "text": "Returns 0xFFFFFFFFFFFFFFFF when len != 0.",
      "asserted_values": ["0xFFFFFFFFFFFFFFFF"],
      "confidence": 1.0,
      "io": {
        "when": "len != 0",
        "returns": "0xFFFFFFFFFFFFFFFF"
      }
    },
    {
      "id": "4",
      "type": "SIDE",
      "text": "Does not write to out.",
      "asserted_values": [],
      "confidence": 1.0
    },
    {
      "id": "5",
      "type": "CF",
      "text": "A loop iterates over each byte in the input.",
      "asserted_values": [],
      "confidence": 1.0
    }
  ],
  "recovered_c": "uint64_t fn_08(const uint8_t *in, size_t len, uint64_t arg, uint8_t *out, size_t out_cap) {\n  if (len != 0) {\n    uint32_t crc = 0xFFFFFFFF;\n    for (size_t i = 0; i < len; i++) {\n      crc ^= in[i];\n      for (int j = 0; j < 8; j++) {\n        crc = -(crc & 1) & 0xf7179bf5 ^ crc >> 1;\n      }\n    }\n    return ~crc;\n  }\n  return VERA_ERR;\n}"
}
